<section aria-label="Service analytics dashboard"><header><h2>{{ __('Service Analytics') }}</h2></header><dl class="grid gap-4 md:grid-cols-4">@foreach($summary as $metric=>$value)<div wire:key="metric-{{ $metric }}"><dt>{{ str_replace('_',' ',ucwords($metric)) }}</dt><dd>{{ number_format($value,2) }}</dd></div>@endforeach</dl><div>@foreach($snapshots as $snapshot)<article wire:key="snapshot-{{ $snapshot->id }}"><strong>{{ $snapshot->metric }}</strong><span>{{ $snapshot->value }}</span><small>{{ $snapshot->period_start?->diffForHumans() }}</small></article>@endforeach</div></section>
